// prisma/schema.prisma (SQLite: local dev + tests) is the single source of truth. The Postgres schema used for
// hosted deployments is derived from it, so the two cannot drift. `--check` fails when the committed copy is stale.
import { readFileSync, writeFileSync } from "node:fs";

const src = readFileSync("prisma/schema.prisma", "utf8");
if (!/datasource db \{\s*provider = "sqlite"/.test(src)) throw new Error("prisma/schema.prisma is not the sqlite source");
const out =
  "// GENERATED by scripts/sync-postgres-schema.mjs from prisma/schema.prisma. Do not edit by hand.\n" +
  src
    .replace(/(datasource db \{\s*provider = )"sqlite"/, '$1"postgresql"')
    // The generated schema lives one directory deeper, so the client output path gains a "../".
    .replace('output   = "../src/generated/prisma"', 'output   = "../../src/generated/prisma"');

if (process.argv.includes("--check")) {
  let current = "";
  try { current = readFileSync("prisma/postgres/schema.prisma", "utf8"); } catch {}
  if (current !== out) {
    console.error("prisma/postgres/schema.prisma is stale. Run: npm run db:sync-pg");
    process.exit(1);
  }
  console.log("postgres schema in sync");
} else {
  writeFileSync("prisma/postgres/schema.prisma", out);
  console.log("wrote prisma/postgres/schema.prisma");
}
